// Pega o CSV como texto vindo do HTTP Request
const csvRaw = $json.data ?? $json.body ?? $json;
const text = (typeof csvRaw === "string") ? csvRaw :
JSON.stringify(csvRaw);

const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
const headers = lines[0].split(",").map(h => h.trim());

const investimentos = lines.slice(1).map(line => {
  const cols = line.split(",").map(c => c.trim());
  const obj = {};
  headers.forEach((h, i) => obj[h] = cols[i] ?? "");

  // normaliza mínimo para número
  obj.minimo = Number(String(obj.minimo).replace(/[^\d]/g, "")) || 0;

  return obj;
});

return [{ json: { investimentos } }];

// ===== Helpers =====
const norm = (s) => String(s ?? "")
  .normalize("NFD").replace(/[\u0300-\u036f]/g, "")
  .toLowerCase().trim();

const pick = (obj, ...keys) => {
  for (const k of Object.keys(obj)) {
    if (keys.includes(norm(k))) return obj[k];
  }
  return "";
};

const toNumber = (v) => {
  if (typeof v === "number") return v;
  const s = String(v ?? "").replace(/[^\d,.-]/g, "");
  // formato BR: 1.000,50 -> 1000.50
  const n = s.includes(",") ? s.replace(/\./g, "").replace(",", ".") : s;
  return Number(n) || 0;
};

const brl = (n) => n.toLocaleString("pt-BR", { style: "currency", currency: "BRL" });

// ===== Entrada (vem do Merge) =====
const item = $input.first().json;
const investimentos = item.investimentos ?? [];

// Aceita: body = [..clientes], body.clientes = [..], ou um único cliente
let body = item.body ?? item;
let clientes = Array.isArray(body) ? body
  : Array.isArray(body.clientes) ? body.clientes
  : [body];

// ===== Catálogo por perfil =====
const catalogo = {};
for (const inv of investimentos) {
  const perfil = norm(pick(inv, "perfil"));
  if (!perfil) continue;
  (catalogo[perfil] ??= []).push({
    produto: pick(inv, "produto"),
    minimo: toNumber(pick(inv, "minimo")),
    rentabilidade: String(pick(inv, "rentabilidade")),
    rentNum: toNumber(pick(inv, "rentabilidade")),
  });
}

// ===== Mensagens por perfil =====
const intro = {
  conservador: "Seu perfil é conservador: priorizamos segurança e liquidez.",
  moderado: "Seu perfil é moderado: um equilíbrio entre segurança e rentabilidade.",
  arrojado: "Seu perfil é arrojado: foco em maior rentabilidade, aceitando mais risco.",
  agressivo: "Seu perfil é agressivo: foco em maior rentabilidade, aceitando mais risco.",
};

// ===== Processa clientes =====
const grupos = {};

for (const c of clientes) {
  const nome = pick(c, "nome");
  const email = pick(c, "email");
  const saldo = toNumber(pick(c, "saldo"));
  const perfilRaw = String(pick(c, "perfil"));
  const perfil = norm(perfilRaw);

  const produtos = catalogo[perfil] ?? [];
  const elegiveis = produtos
    .filter((p) => p.minimo <= saldo)
    .sort((a, b) => b.rentNum - a.rentNum);
  const indisponiveis = produtos.filter((p) => p.minimo > saldo);

  const primeiroNome = String(nome).split(" ")[0] || "cliente";
  let mensagem = `Olá, ${primeiroNome}! ${intro[perfil] ?? `Seu perfil é ${perfilRaw}.`}\n`;
  mensagem += `Seu saldo atual é ${brl(saldo)}.\n\n`;

  if (!produtos.length) {
    mensagem += "Ainda não temos produtos cadastrados para o seu perfil.";
  } else if (elegiveis.length) {
    mensagem += "Opções disponíveis para você hoje:\n";
    elegiveis.forEach((p) => {
      mensagem += `• ${p.produto} — rentabilidade ${p.rentabilidade} (mínimo ${brl(p.minimo)})\n`;
    });
    if (indisponiveis.length) {
      const prox = indisponiveis.sort((a, b) => a.minimo - b.minimo)[0];
      mensagem += `\nDica: com ${brl(prox.minimo)} você também acessa ${prox.produto}.`;
    }
  } else {
    const prox = [...produtos].sort((a, b) => a.minimo - b.minimo)[0];
    mensagem += `Seu saldo ainda não atinge o mínimo dos produtos do seu perfil. `
      + `O mais acessível é ${prox.produto}, a partir de ${brl(prox.minimo)}.`;
  }

  const chave = perfil || "sem_perfil";
  (grupos[chave] ??= []).push({
    nome,
    email,
    saldo,
    perfil: perfilRaw,
    produtosRecomendados: elegiveis.map(({ produto, minimo, rentabilidade }) => ({ produto, minimo, rentabilidade })),
    mensagem: mensagem.trim(),
  });
}

// ===== Saída (1 item, pois o Respond to Webhook devolve $json) =====
return [{
  json: {
    totalClientes: clientes.length,
    perfis: Object.fromEntries(
      Object.entries(grupos).map(([perfil, lista]) => [perfil, { quantidade: lista.length, clientes: lista }])
    ),
  },
}];

// Pega a estrutura principal vinda do nó anterior (considerando que seja um array ou objeto direto)
const inputData = $json.perfis ? [$json] : ($json[0]?.perfis ? $json : $input.all());

// Extrai todos os clientes de dentro de cada perfil (conservador, moderado, arrojado)
let clientesList = [];

inputData.forEach(item => {
  const perfis = item.perfis || {};
  Object.values(perfis).forEach(perfilObj => {
    if (perfilObj && Array.isArray(perfilObj.clientes)) {
      clientesList = clientesList.concat(perfilObj.clientes);
    }
  });
});

// Transforma cada cliente no formato de saída desejado
const out = clientesList.map(c => {
  // Como o saldo já vem como número no JSON, garantimos o tratamento de conversão caso necessário
  const saldoNum = Number(c.saldo) || 0;

  return {
    json: {
      email_to: String(c.email || "").trim(),
      nome: String(c.nome || "").trim(),
      perfil: c.perfil,
      saldo_texto: `R$ ${saldoNum.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`,
      saldo_num: saldoNum,
      recomendacao: c.produtosRecomendados ? c.produtosRecomendados.map(p => p.produto).join(", ") : "",
      motivo: "", // Campo ajustável conforme sua regra de negócio
      mensagem_base: c.mensagem || "",
      copy_rules: {
        idioma: "pt-BR",
        tom: "amigável e profissional",
        tamanho: "curto (4-6 linhas)",
        evitar: ["promessas de ganho", "garantias", "linguagem agressiva"]
      }
    }
  };
});

return out;

